function numSub(s) {
  // Extend a substring from every start for as long as it stays all '1'.
  let count = 0;
  for (let i = 0; i < s.length; i++) {
    for (let j = i; j < s.length && s[j] === '1'; j++) count++;
  }
  return count % 1000000007;
}

