function generate(rand, size) {
  const n = size === 'large' ? 9000 + Math.floor(rand() * 1001) : 1 + Math.floor(rand() * 14);
  // Mostly-ones strings make long runs; sparse ones make many short runs.
  const density = [0.1, 0.5, 0.8, 0.97, 1][Math.floor(rand() * 5)];
  let s = '';
  for (let i = 0; i < n; i++) s += rand() < density ? '1' : '0';
  return [s];
}
